import {initHeroVideo} from './hero-video.mjs';
import {KEY,money,inStock,discount,normalize,catalogue,filterProducts,validateProduct,saleProduct,basketSummary,enquiryMessage,defaults,fragranceProfile,edits,matchesCollection,catalogueDisplay} from './core.mjs';
const $=(q,r=document)=>r.querySelector(q), $$=(q,r=document)=>[...r.querySelectorAll(q)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=id=>`<svg aria-hidden="true"><use href="#${id}-icon"/></svg>`;
const imageURL=s=> /^(assets\/[a-zA-Z0-9._-]+|data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+)$/.test(s||'')?s:'assets/khamrah.jpg';
const safeSource=s=>{try{const u=new URL(s);return u.protocol==='https:'?esc(u.href):''}catch{return ''}};
let storageNotice='';
function read(key,fallback){try{const v=localStorage.getItem(key);return v?JSON.parse(v):fallback}catch{storageNotice='Browser storage could not be read. You can explore, but changes may not persist.';return fallback}}
let state=read(KEY,defaults());if(state?.version!==1||!Array.isArray(state.products)||!state.settings)state=defaults();
let basket=read(KEY+'-bag',[]),saved=read(KEY+'-saved',[]);if(!Array.isArray(basket))basket=[];if(!Array.isArray(saved))saved=[];
let filters={query:'',brand:'',budget:'',stock:'',sort:'curated',kind:'all',collection:''},adminTab='catalogue',adminQuery='',adminScope='active',toastTimer,modalType='',currentId='',uploadImage='',returnFocus=null;
const modal=$('#modal');
let heroMotion;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200)}
function write(key,data){try{localStorage.setItem(key,JSON.stringify(data));return true}catch{toast('Could not save. Browser storage is full or disabled. Try a smaller image.');return false}}
function commit(next){if(!write(KEY,next))return false;state=next;renderStore();if(location.hash==='#admin')renderAdmin();return true}
function updateProduct(id,fn){const next=structuredClone(state);const index=next.products.findIndex(p=>p.id===id);if(index<0)return false;next.products[index]=fn(next.products[index]);return commit(next)}
function saveBag(next){if(!write(KEY+'-bag',next))return false;basket=next;renderCounters();return true}
function renderCounters(){const count=basket.reduce((n,x)=>n+x.qty,0);$('#bag-count').textContent=count;$('.bag-button').setAttribute('aria-label',`Open enquiry basket, ${count} items`);$('#saved-count').textContent=saved.length||''}
function favourite(id){const next=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];if(write(KEY+'-saved',next)){saved=next;renderStore();if(modalType==='product')openProduct(currentId,false);toast(saved.includes(id)?'Saved to your favourites.':'Removed from favourites.')}}
function addToBag(id,qty=1){const p=state.products.find(p=>p.id===id);if(!inStock(p))return toast('This variant is sold out or unavailable.');const previous=basket.find(i=>i.id===id)?.qty||0;if(!Number.isInteger(qty)||qty<1||qty+previous>p.quantity)return toast(`Only ${p.quantity} available in this sample inventory${previous?`; ${previous} already in your bag`:''}.`);const next=structuredClone(basket),line=next.find(i=>i.id===id);if(line)line.qty+=qty;else next.push({id,qty});if(saveBag(next))toast(`${p.name} · ${p.size} ml added to your enquiry bag.`)}
function photoStyle(p){const f=fragranceProfile(p);return `--bottle-scale:${p.image?.startsWith('data:')?'.9':f.scale};--bottle-position:${f.position}`}
function card(p){const stock=inStock(p),profile=fragranceProfile(p),decant=p.format==='Full bottle'&&catalogue(state.products).some(x=>x.group===p.group&&x.format==='Decant');return `<article class="product-card"><a class="product-photo" href="#product/${esc(p.id)}" style="${photoStyle(p)}" aria-label="View ${esc(p.brand+' '+p.name+' '+p.size+' ml '+p.format)}"><img src="${imageURL(p.image)}" alt="${esc(p.brand+' '+p.name)} original bottle${p.format==='Decant'?' (fragrance reference; not decant packaging)':''}" loading="lazy" decoding="async" width="640" height="640">${!stock?'<span class="photo-tag sold">Sold out</span>':''}<span class="photo-format">${esc(p.format)}</span><span class="photo-discover">Discover ↗</span></a><button class="save-btn ${saved.includes(p.id)?'saved':''}" data-action="save" data-id="${esc(p.id)}" aria-label="${saved.includes(p.id)?'Unsave':'Save'} ${esc(p.name+' '+p.size+' ml '+p.format)}" aria-pressed="${saved.includes(p.id)}">${icon('heart')}</button><div class="product-copy"><div class="brand-row"><span>${esc(p.brand)}</span><span class="stock-dot ${stock?'':'out'}">${stock?'Available':'Sold out'}</span></div><a class="product-name" href="#product/${esc(p.id)}">${esc(p.name)}</a><p class="scent-family">${esc(profile.family)}</p><p class="product-meta">${p.size} ml · ${esc(p.format)}${decant?'<span class="decant-note">Also in discovery sizes</span>':''}</p><div class="product-bottom"><span class="price">${money(p.price)}<small>Sample price</small></span><button class="add-btn" data-action="add" data-id="${esc(p.id)}" ${stock?'':'disabled'} aria-label="Add ${esc(p.name+' '+p.size+' ml '+p.format)} to enquiry bag">${icon('plus')}</button></div></div></article>`}
function renderEdits(){const products=catalogue(state.products).filter(p=>p.format==='Full bottle');$('#scent-edits-grid').innerHTML=edits.map(edit=>{const list=products.filter(p=>matchesCollection(p,edit.id)),p=list.find(p=>p.group===edit.image)||list[0];return `<button class="scent-edit edit-${edit.id}" data-edit="${edit.id}" ${list.length?'':'disabled'}><span class="edit-number">${edit.number} / THE EDIT</span>${p?`<div class="edit-bottle" style="${photoStyle(p)}"><img src="${imageURL(p.image)}" alt="" width="640" height="640" loading="lazy"></div>`:''}<span class="edit-copy"><strong>${edit.name}</strong><span>${edit.line}</span><small>${list.length} ${list.length===1?'fragrance':'fragrances'} <b>↗</b></small></span></button>`}).join('')}
function renderStore(){
 const products=catalogue(state.products),deals=products.filter(p=>p.deal);$('#deals-grid').innerHTML=deals.slice(0,4).map(card).join('')||'<div class="empty-state"><h3>A fresh edit is on its way.</h3><p>No demo deals are selected. Explore the collection below.</p></div>';
 const brand=$('#brand-filter'),val=filters.brand;brand.innerHTML='<option value="">All brands</option>'+[...new Set(products.map(p=>p.brand))].sort().map(b=>`<option value="${esc(b)}">${esc(b)}</option>`).join('');brand.value=val;if(brand.value!==val)filters.brand='';
 renderCatalogue();renderEdits();renderFeatured();renderCounters();$('#about-text').textContent=state.settings.about;$('#ordering-text').textContent=state.settings.ordering;$('#shipping-text').textContent=state.settings.shipping;$('#payment-text').textContent=state.settings.payment;$('#review-text').textContent=state.settings.reviews;$('#reviews-panel').hidden=!state.settings.reviews||state.settings.reviews===defaults().settings.reviews;
 $('#faq-list').innerHTML=state.settings.faq.split('\n').filter(Boolean).map(line=>{const [q,...a]=line.split('|');return `<details><summary>${esc(q)}</summary><p>${esc(a.join('|')||'Answer pending owner approval.')}</p></details>`}).join('');
 $('#year').textContent=new Date().getFullYear();
}
function renderCatalogue(){const matches=filterProducts(state.products,filters,saved),list=catalogueDisplay(matches,filters.kind);$('#catalogue-grid').innerHTML=list.map(card).join('')||`<div class="empty-state"><h3>${filters.kind==='saved'?'A shortlist of your own.':'Nothing quite matches yet.'}</h3><p>${filters.kind==='saved'?'Tap the heart on a fragrance to save it here.':'Try another search or clear your filters.'}</p><button class="btn outline" data-action="clear-filters">Explore all fragrances ↗</button></div>`;$('#results-count').textContent=`${list.length} ${filters.kind==='all'?'fragrances':'variants'}`;$$('[data-kind]').forEach(b=>{b.classList.toggle('active',b.dataset.kind===filters.kind);b.setAttribute('aria-pressed',b.dataset.kind===filters.kind)});const n=[filters.brand,filters.budget,filters.stock].filter(Boolean).length;$('#filter-count').textContent=n?`(${n})`:'';const edit=edits.find(e=>e.id===filters.collection);$('#active-edit').hidden=!edit;$('#active-edit').innerHTML=edit?`<span>Browsing the edit <b>${edit.name}</b></span><button data-action="clear-edit" aria-label="Remove ${edit.name} collection filter">Clear edit ×</button>`:'';$$('[data-edit]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.edit===filters.collection)))}
function renderFeatured(){const list=catalogue(state.products).filter(p=>p.featured).sort((a,b)=>a.featureOrder-b.featureOrder);$('#featured').hidden=!list.length;$('#featured').innerHTML=`<div class="featured-heading"><div><p class="eyebrow">FROM THE DRIP & DUSK SHELF</p><h2>A closer look.</h2></div><p>Some scents deserve a little more of your attention. Meet the featured edit.</p></div><div class="feature-grid">${list.slice(0,2).map((p,i)=>`<article class="feature-card"><div class="feature-bottle" style="${photoStyle(p)}"><img src="${imageURL(p.image)}" alt="${esc(p.name)}" width="640" height="640" loading="lazy"></div><div class="feature-copy"><p class="eyebrow">${String(i+1).padStart(2,'0')} / ${esc(p.brand.toUpperCase())}</p><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><span class="price">${money(p.price)} <small> / ${p.size} ml · ${esc(p.format)}</small></span><a class="text-link" href="#product/${esc(p.id)}">Discover the fragrance ↗</a></div></article>`).join('')}</div>`}
function clearFilters(){filters={query:'',brand:'',budget:'',stock:'',sort:'curated',kind:'all',collection:''};$('#catalogue-search').value='';['brand','budget','stock'].forEach(x=>$('#'+x+'-filter').value='');$('#sort-filter').value='curated';renderCatalogue()}
function openModal(title,body,type,eyebrow='DRIP & DUSK'){if(modalType==='product'&&type!=='product'&&location.hash.startsWith('#product/'))history.replaceState(null,'','#collection');if(!modal.open)returnFocus=document.activeElement;modalType=type;modal.classList.toggle('product-dialog',type==='product');$('#modal-content').innerHTML=`<div class="modal-head"><div><p class="eyebrow">${esc(eyebrow)}</p><h2 id="modal-title">${esc(title)}</h2></div><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();document.body.classList.add('modal-open')}
function closeModal(navigate=true){const was=modalType;modal.close();document.body.classList.remove('modal-open');modalType='';if(navigate&&was==='product'&&location.hash.startsWith('#product/')){history.replaceState(null,'','#collection')}if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true})}
function openProduct(id,reset=true){
 const p=state.products.find(p=>p.id===id&&!p.hidden&&!p.archived);currentId=id;
 if(!p)return openModal('This fragrance is unavailable.','<p>It may have been hidden or archived by the seller.</p><button class="btn outline" data-action="close">Back to collection</button>','product');
 const stock=inStock(p),variants=catalogue(state.products).filter(x=>x.group===p.group),notes=p.notes.split('/'),profile=fragranceProfile(p);
 openModal(p.name,`<div class="detail-grid"><div class="detail-gallery"><div class="detail-image" style="${photoStyle(p)}"><img src="${imageURL(p.image)}" alt="${esc(p.brand+' '+p.name)} original bottle" width="640" height="640"></div><div class="gallery-controls" role="group" aria-label="Product image view"><button class="active" data-action="image-view" data-view="bottle" aria-pressed="true">Bottle view</button><button data-action="image-view" data-view="detail" aria-pressed="false">Label detail</button><span>↗ A closer look</span></div><p class="image-caption">${p.format==='Decant'?'Original bottle reference. Your decant comes in a separate seller-filled atomiser.':'Brand product reference. Ask the seller for photographs of the actual bottle and packaging.'}</p></div><div class="detail-copy"><p class="eyebrow">${esc(p.brand)} / THE FRAGRANCE EDIT</p><h3>${esc(p.name)}</h3><p class="detail-family">${esc(profile.family)}</p><p>${esc(p.description)}</p><dl class="fragrance-facts"><div><dt>Our pairing</dt><dd>${esc(profile.pairing)}</dd></div><div><dt>Concentration</dt><dd>${esc(profile.concentration)}</dd></div></dl><span class="field-label">CHOOSE YOUR SIZE & FORMAT</span><div class="variant-options">${variants.map(v=>`<a class="${v.id===p.id?'active':''}" href="#product/${esc(v.id)}" ${v.id===p.id?'aria-current="true"':''}>${v.size} ml <span>${esc(v.format)}${!inStock(v)?' · Sold out':''}</span></a>`).join('')}</div><p class="condition-copy">${esc(p.condition)}</p><div class="detail-price">${money(p.price)} <small>Sample price</small></div><p class="stock-dot ${stock?'':'out'}">${stock?`${p.quantity} available · sample inventory`:'Sold out · unavailable for enquiry'}</p><div class="quantity-row"><div class="quantity-control"><button data-action="detail-minus" aria-label="Decrease quantity" ${stock?'':'disabled'}>−</button><input id="detail-quantity" type="number" min="1" max="${p.quantity}" value="1" aria-label="Quantity" ${stock?'':'disabled'}><button data-action="detail-plus" aria-label="Increase quantity" ${stock?'':'disabled'}>+</button></div><button class="btn" data-action="detail-add" data-id="${esc(p.id)}" ${stock?'':'disabled'}>${stock?'Add to enquiry bag':'Sold out'} ${icon('bag')}</button></div><div class="detail-actions"><button class="text-link" data-action="enquire-product" data-id="${esc(p.id)}" ${stock?'':'disabled'}>Ask about this fragrance ${icon('chat')}</button><button class="text-link" data-action="share-product" data-id="${esc(p.id)}">Copy product link ↗</button></div><p class="fineprint">Seller confirms availability, final price, delivery charges and payment before purchase.</p></div></div><div class="notes-section"><p class="eyebrow">FROM FIRST IMPRESSION TO DRY-DOWN</p><h4>The scent, in notes.</h4>${notes.length===3?`<div class="note-pyramid">${notes.map((s,i)=>`<div class="note-stage"><span>0${i+1}</span><h5>${['Opening','Heart','Base'][i]}</h5><p>${esc(s.trim())}</p></div>`).join('')}</div>`:`<p class="fineprint">${esc(p.notes)}</p>`}${safeSource(p.source)?`<a href="${safeSource(p.source)}" target="_blank" rel="noopener noreferrer">Read the brand’s fragrance information ↗</a>`:''}<p class="fineprint">Style and occasion pairings are our editorial suggestions. Longevity and projection depend on skin, application and conditions.</p></div><div class="purchase-clarity"><h4>Before you make it yours.</h4><details><summary>Full bottle or decant?</summary><p>Full bottles and decants are separate variants. A decant is transferred by the seller into a smaller atomiser; the original bottle pictured is a fragrance reference. Ask for the actual atomiser size, packaging and preparation details.</p></details><details><summary>Sourcing & bottle condition</summary><p>Drip & Dusk is a multi-brand retailer. Ask the seller to confirm the sourcing, batch and condition of your selected bottle. Brand photographs do not imply authorised-dealer status.</p></details><details><summary>Delivery, payment & returns</summary><p>${esc(state.settings.shipping)}</p><p>${esc(state.settings.payment)}</p></details></div><div class="detail-sticky"><div><b>${money(p.price)}</b><span>${p.size} ml · ${esc(p.format)}</span></div><button class="btn" data-action="detail-add" data-id="${esc(p.id)}" ${stock?'':'disabled'}>${stock?'Add to bag':'Sold out'} ${icon('bag')}</button></div>`,'product',p.brand.toUpperCase());
 if(reset)modal.scrollTop=0;
}
function openBasket(){const s=basketSummary(state.products,basket);openModal('Your enquiry bag.',basket.length?`<div class="notice">A shortlist, ready for a conversation. <strong>Nothing is reserved.</strong> The seller confirms prices, availability, shipping and payment.</div><div class="basket-list">${s.lines.map(l=>`<div class="basket-line">${l.p?`<img src="${imageURL(l.p.image)}" alt="${esc(l.p.name)}" width="70" height="85">`:'<span></span>'}<div><h3>${esc(l.p?`${l.p.brand} ${l.p.name}`:'Removed fragrance')}</h3><p>${l.p?`${l.p.size} ml · ${esc(l.p.format)} · ${money(l.p.price)} each`:'This product has been removed.'}</p><div class="quantity-control"><button data-action="bag-minus" data-id="${esc(l.id)}" aria-label="Decrease quantity for ${esc(l.p?.name||'removed item')}">−</button><input type="number" value="${l.qty}" min="1" max="${l.p?.quantity||0}" data-bag-qty="${esc(l.id)}" aria-label="Quantity for ${esc(l.p?.name||'removed item')}"><button data-action="bag-plus" data-id="${esc(l.id)}" aria-label="Increase quantity for ${esc(l.p?.name||'removed item')}">+</button></div><button class="remove-btn" data-action="bag-remove" data-id="${esc(l.id)}">Remove</button></div><div class="line-total">${l.valid?money(l.subtotal):`<span class="invalid">${!inStock(l.p)?'Unavailable — remove to continue':`Only ${l.p.quantity} available — adjust quantity`}</span>`}</div></div>`).join('')}</div><div class="basket-total"><span>Estimated total${!s.valid?' (valid items only)':''}</span><b>${money(s.total)}</b></div><button class="btn full" data-action="preview-basket" ${s.valid?'':'disabled'}>${state.settings.whatsapp?'Review WhatsApp enquiry':'Preview WhatsApp enquiry'} ${icon('chat')}</button><p class="fineprint">Sample demo data · No payment collected. ${state.settings.whatsapp?'You will review the message before opening WhatsApp.':'No business number is configured. This demo will only preview the message.'}</p>`:`<div class="empty-state"><h3>A little room for discovery.</h3><p>Add a bottle or decant to start your enquiry.</p><button class="btn" data-action="browse">Explore the collection ↗</button></div>`,'basket');modal.scrollTop=0}
function changeBag(id,qty){const p=state.products.find(x=>x.id===id);if(!Number.isInteger(qty)||qty<1)return toast('Enter a whole quantity of at least 1, or remove the item.');if(!inStock(p)||qty>p.quantity)return toast(`This quantity is unavailable. ${p&&inStock(p)?`Only ${p.quantity} available.`:'Please remove this item.'}`);const next=basket.map(x=>x.id===id?{...x,qty}:x);if(saveBag(next))openBasket()}
function previewMessage(items=basket,contact=false){let message;try{message=contact?'Hello Drip & Dusk! I’d like to ask about your fragrance collection. Please share current availability, prices, shipping and payment details. This is a demo enquiry.':enquiryMessage(state.products,items)}catch(e){return toast(e.message)}const num=state.settings.whatsapp.replace(/\D/g,'');const valid=/^[1-9]\d{7,14}$/.test(num);openModal('A conversation, ready to send.',`<div class="notice">${valid?'Review your message below. Opening WhatsApp does not send it automatically or confirm an order.':'<strong>Preview only.</strong> No business WhatsApp number is configured. This message will not contact anyone.'}</div><label class="field-label" for="message-preview">WHATSAPP MESSAGE</label><textarea class="message-preview" id="message-preview" readonly>${esc(message)}</textarea><div class="modal-buttons"><button class="btn outline" data-action="copy-message">Copy message</button>${valid?`<a class="btn" href="https://wa.me/${num}?text=${encodeURIComponent(message)}" target="_blank" rel="noopener noreferrer">Open WhatsApp ${icon('chat')}</a>`:'<button class="btn" data-action="close">Done</button>'}</div><p class="fineprint">Availability, final pricing, shipping and payment are confirmed by the seller. No stock is reserved.</p>`,'message')}
async function copy(text,label){try{await navigator.clipboard.writeText(text);toast(label)}catch{openModal('Copy this text.',`<p class="fineprint">Clipboard access is unavailable. Select and copy the text below.</p><textarea class="message-preview" readonly>${esc(text)}</textarea>`,'copy')}}
function renderAdmin(){
 const all=state.products,active=all.filter(p=>!p.archived);$('#admin').innerHTML=`<a href="#collection" class="text-link">← Back to storefront</a><div class="admin-top"><div><p class="eyebrow">DRIP & DUSK / OWNER STUDIO</p><h1>A considered collection.</h1><p>Your catalogue, your edit. Manage it all here.</p></div><button class="btn" data-action="new-product">${icon('plus')} Add fragrance</button></div><div class="notice"><strong>Browser-local demo — no authentication or production security.</strong> Changes apply only to this browser/device and are editable by anyone using it. A live store needs authenticated, server-enforced admin access and a shared database. Sales made outside the website must be recorded manually unless a future integration is added.</div><div class="admin-stats"><div class="stat"><b>${active.length}</b><span>Catalogue variants</span></div><div class="stat"><b>${active.filter(inStock).length}</b><span>In stock & visible</span></div><div class="stat"><b>${active.filter(p=>p.deal&&!p.hidden).length}</b><span>In the deals edit</span></div><div class="stat"><b>${active.filter(p=>p.featured&&!p.hidden).length}</b><span>Featured fragrances</span></div></div><div class="admin-tabs"><button data-admin-tab="catalogue" class="${adminTab==='catalogue'?'active':''}">Catalogue</button><button data-admin-tab="settings" class="${adminTab==='settings'?'active':''}">Business & ordering</button><button data-admin-tab="handover" class="${adminTab==='handover'?'active':''}">Demo guide</button></div><div id="admin-content"></div><div class="admin-footer">DEMO STUDIO · SAMPLE DATA · CHANGES SAVED ON THIS DEVICE ONLY</div>`;
 if(adminTab==='catalogue'){ $('#admin-content').innerHTML=`<div class="admin-search"><label class="search-box">${icon('search')}<input id="admin-search" type="search" placeholder="Search names, brands or sizes…" value="${esc(adminQuery)}" aria-label="Search owner catalogue"></label><select id="admin-scope" aria-label="Product visibility"><option value="active">Active catalogue</option><option value="hidden">Hidden products</option><option value="archived">Archive</option></select></div><div id="admin-products"></div>`;$('#admin-scope').value=adminScope;renderAdminProducts()}
 if(adminTab==='settings')renderSettings();if(adminTab==='handover')$('#admin-content').innerHTML=`<div class="settings-form"><h3>Show Deepak the complete experience.</h3><p>Start in the collection, open a fragrance, switch to the 10 ml decant, choose a quantity and preview the WhatsApp message. A configured number opens WhatsApp only after the message review.</p><h3>Make a change, see it immediately.</h3><p>In Catalogue, tap a price for a quick update. Use “Sold out” to stop enquiries, “Duplicate” to create a different size, or “Edit” for the full details. Deals and Featured checkboxes control each edit; lower display-order numbers come first.</p><h3>Keep inventory honest.</h3><p>“Record sale” deducts a whole quantity and marks stock sold out at zero. Enquiries never deduct inventory. Record sales from WhatsApp, Instagram or other channels manually unless a future integration is added.</p><h3>What is simulated.</h3><p>All prices, offers, conditions, stock, decant availability and business policies are demo data. Original bottle photos identify decants but do not show their packaging. Hero films are supplied AI-generated product scenes. No customer data, payments, reservations, authentication or confirmed orders are involved.</p><h3>Before launch.</h3><p>Add a backend database, secure owner authentication and server-enforced permissions; move uploads to durable storage; confirm image usage rights, exact products, notes, prices and stock; add Deepak’s real WhatsApp number and approved shipping, payment, privacy and return policies. Publish real reviews only with permission. Review accessibility, data handling and mobile performance on the production domain.</p><p>Use Business & ordering → Reset demo data to restore this browser’s original catalogue, settings, bag and favourites.</p></div>`;
}
function renderAdminProducts(){const list=state.products.filter(p=>(adminScope==='archived'?p.archived:adminScope==='hidden'?!p.archived&&p.hidden:!p.archived)&&adminQuery.trim().split(/\s+/).every(term=>normalize([p.name,p.brand,p.size,p.format].join(' ')).includes(normalize(term)))).sort((a,b)=>a.order-b.order);$('#admin-products').innerHTML=list.length?`<table class="admin-table"><thead><tr><th>FRAGRANCE / VARIANT</th><th>SELLING PRICE</th><th>STOCK</th><th>EDIT</th><th>ACTIONS</th></tr></thead><tbody>${list.map(p=>`<tr><td><div class="admin-product"><img src="${imageURL(p.image)}" alt="" width="47" height="58"><div><h3>${esc(p.name)}</h3><p>${esc(p.brand)} · ${p.size} ml · ${esc(p.format)}</p></div></div></td><td><span class="admin-mobile-label">Price</span><button class="admin-price" data-action="price" data-id="${esc(p.id)}" aria-label="Change price of ${esc(p.name+' '+p.size+' ml')}">${money(p.price)} ↗</button></td><td><span class="status-pill ${inStock(p)?'':'out'}">${p.archived?'Archived':p.hidden?'Hidden':inStock(p)?p.quantity+' in stock':'Sold out'}</span><br><button class="text-link" data-action="stock-toggle" data-id="${esc(p.id)}" style="font-size:8px;min-height:28px">${p.available&&p.quantity>0?'Mark sold out':'Restock / edit'}</button></td><td><span class="admin-mobile-label">Edit</span>${p.deal?'Deal ':''}${p.featured?'· Featured':''}${!p.deal&&!p.featured?'—':''}<br><span class="fineprint">Order ${p.order} / Feature ${p.featureOrder}</span></td><td><div class="admin-row-actions">${p.archived?`<button class="small-btn" data-action="restore" data-id="${esc(p.id)}">Restore</button><button class="small-btn" data-action="delete" data-id="${esc(p.id)}">Delete</button>`:`<button class="small-btn" data-action="edit" data-id="${esc(p.id)}">Edit</button><button class="small-btn" data-action="duplicate" data-id="${esc(p.id)}">Duplicate</button><button class="small-btn" data-action="sale" data-id="${esc(p.id)}" ${inStock(p)?'':'disabled'}>Record sale</button><button class="small-btn" data-action="hide" data-id="${esc(p.id)}">${p.hidden?'Show':'Hide'}</button><button class="small-btn" data-action="archive" data-id="${esc(p.id)}">Archive</button>`}</div></td></tr>`).join('')}</tbody></table>`:'<div class="empty-state"><h3>No fragrances here.</h3><p>Try a different search or visibility filter.</p></div>'}
const field=(label,name,value,type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
function editProduct(id,duplicate=false){const existing=state.products.find(p=>p.id===id);const p=existing?structuredClone(existing):{id:'p-'+crypto.randomUUID(),group:'g-'+crypto.randomUUID(),brand:'',name:'',size:100,format:'Full bottle',condition:'',price:'',reference:null,quantity:1,available:true,description:'',notes:'',image:'',source:'',deal:false,featured:false,hidden:false,archived:false,order:state.products.length,featureOrder:state.products.length};if(duplicate){p.id='p-'+crypto.randomUUID();p.deal=false;p.featured=false;p.order=state.products.length;p.quantity=1;p.available=true;p.reference=null;p.hidden=false;p.archived=false}uploadImage=p.image;currentId=p.id;
 openModal(duplicate?'Another size, same signature.':existing?'Edit fragrance.':'Add a fragrance.',`<form id="product-form"><div class="notice">${duplicate?'Set the new size, format, price and quantity before saving. This variant will share the same product detail selector.':'Each listing is one exact size and format. Duplicate it to add another variant.'}</div><div class="form-grid">${field('Brand *','brand',p.brand,'text','required maxlength="80"')}${field('Exact product / variant name *','name',p.name,'text','required maxlength="160"')}${field('Bottle or decant size (ml) *','size',p.size,'number','min="1" max="2000" step="1" required')}<label>Format *<select name="format"><option ${p.format==='Full bottle'?'selected':''}>Full bottle</option><option ${p.format==='Decant'?'selected':''}>Decant</option></select></label><label class="span-2">Condition / bottle type<input name="condition" value="${esc(p.condition)}" maxlength="160" placeholder="e.g. Sealed retail bottle, opened bottle, seller-filled atomiser"></label>${field('Selling price (₹) *','price',p.price,'number','min="1" max="1000000" step="1" required')}${field('Reference price (₹) — optional','reference',p.reference??'','number','min="1" max="2000000" step="1"')}${field('Available quantity *','quantity',p.quantity,'number','min="0" max="10000" step="1" required')}<label>Availability<select name="available"><option value="true" ${p.available?'selected':''}>In stock</option><option value="false" ${!p.available?'selected':''}>Sold out / unavailable</option></select></label><label class="span-2">Short description<textarea name="description" maxlength="1200">${esc(p.description)}</textarea></label><label class="span-2">Fragrance notes — opening / heart / base<textarea name="notes" maxlength="1500" placeholder="Only add verified notes. Separate the three stages with /">${esc(p.notes)}</textarea></label><label>Scent collection<select name="scentEdit"><option value="">Use original edit / none</option>${[['fresh','Fresh daily'],['warm','Warm & spiced / After dark'],['dark','After dark'],['soft','Soft & floral']].map(([value,label])=>`<option value="${value}" ${p.scentEdit===value?'selected':''}>${label}</option>`).join('')}</select></label>${field('Scent family — optional' ,'family',p.family||fragranceProfile(p).family)}${field('Concentration — verified only','concentration',p.concentration||'','text','placeholder="e.g. Eau de Parfum, once confirmed"')}${field('Occasion pairing — editorial','pairing',p.pairing||fragranceProfile(p).pairing)}${field('Catalogue display order','order',p.order,'number','step="1" required')}${field('Featured display order','featureOrder',p.featureOrder,'number','step="1" required')}<label class="span-2">Product image <img id="upload-preview" class="upload-preview" src="${imageURL(p.image)}" alt="Product image preview"><input type="file" id="image-upload" accept="image/png,image/jpeg,image/webp"><small>Use a centred bottle on a light background with clear space around it. JPG, PNG or WebP, up to 8 MB. Stored locally after resizing. A sample bottle is shown until you upload your own.</small></label><div class="span-2 checkboxes"><label><input name="deal" type="checkbox" ${p.deal?'checked':''}> Show in deals</label><label><input name="featured" type="checkbox" ${p.featured?'checked':''}> Feature this product</label><label><input name="hidden" type="checkbox" ${p.hidden?'checked':''}> Hide from storefront</label></div></div><p id="product-error" class="form-error" role="alert"></p><div class="modal-buttons"><button class="btn outline" type="button" data-action="close">Cancel</button><button class="btn" type="submit">Save fragrance ↗</button></div></form>`,'edit','OWNER STUDIO · LOCAL DEMO');
 $('#product-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),product={...p,brand:f.get('brand').trim(),name:f.get('name').trim(),size:Number(f.get('size')),format:f.get('format'),condition:f.get('condition').trim()||'Condition pending owner confirmation',price:Number(f.get('price')),reference:f.get('reference')===''?null:Number(f.get('reference')),quantity:Number(f.get('quantity')),available:f.get('available')==='true',description:f.get('description').trim(),notes:f.get('notes').trim()||'Notes pending owner verification.',scentEdit:f.get('scentEdit'),family:f.get('family').trim(),concentration:f.get('concentration').trim(),pairing:f.get('pairing').trim(),image:uploadImage,order:Number(f.get('order')),featureOrder:Number(f.get('featureOrder')),deal:f.has('deal'),featured:f.has('featured'),hidden:f.has('hidden')};const err=validateProduct(product)||(!uploadImage?'Upload a product image before saving a new fragrance.':'');if(err){$('#product-error').textContent=err;return}const next=structuredClone(state),index=next.products.findIndex(x=>x.id===product.id);if(index<0)next.products.push(product);else next.products[index]=product;if(commit(next)){closeModal();toast('Fragrance saved. Storefront updated on this device.')}});
 $('#image-upload').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024){$('#product-error').textContent='Choose a JPG, PNG or WebP image smaller than 8 MB.';e.target.value='';return}const submit=$('#product-form [type=submit]');submit.disabled=true;try{const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,900/Math.max(bitmap.width,bitmap.height));canvas.width=bitmap.width*scale;canvas.height=bitmap.height*scale;const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();uploadImage=canvas.toDataURL('image/jpeg',.82);$('#upload-preview').src=uploadImage;$('#product-error').textContent='';toast('Image ready. Save the fragrance to keep it.')}catch{$('#product-error').textContent='This image could not be opened. Try a different file.'}finally{submit.disabled=false}});
}
function priceModal(id){const p=state.products.find(p=>p.id===id);openModal('A quick price update.',`<p>${esc(p.name)} · ${p.size} ml · ${esc(p.format)}</p><form id="quick-price" class="form-grid">${field('Selling price (₹)','price',p.price,'number','required min="1" max="1000000" step="1"')}${field('Reference price (₹) — optional','reference',p.reference??'','number','min="1" step="1"')}<p id="price-error" class="form-error span-2" role="alert"></p><button class="btn span-2" type="submit">Save price</button></form>`,'price','OWNER STUDIO');$('#quick-price').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),next={...p,price:Number(f.get('price')),reference:f.get('reference')?Number(f.get('reference')):null},error=validateProduct(next);if(error){$('#price-error').textContent=error;return}if(updateProduct(id,()=>next)){closeModal();toast('Price saved. The storefront and bag use the updated price.')}})}
function saleModal(id){const p=state.products.find(p=>p.id===id);openModal('Record an outside sale.',`<p>${esc(p.name)} · ${p.size} ml · ${esc(p.format)}</p><div class="notice">${p.quantity} units in sample stock. This action deducts inventory. Enquiries do not.</div><form id="sale-form" class="form-grid">${field('Quantity sold','quantity',1,'number',`required min="1" max="${p.quantity}" step="1"`)}<p class="fineprint">At zero stock, this variant will be marked sold out automatically.</p><p id="sale-error" class="form-error span-2" role="alert"></p><button class="btn span-2" type="submit">Record sale & update stock</button></form>`,'sale','OWNER STUDIO');$('#sale-form').addEventListener('submit',e=>{e.preventDefault();try{const qty=Number(new FormData(e.currentTarget).get('quantity')),current=state.products.find(x=>x.id===id),next=saleProduct(current,qty);if(updateProduct(id,()=>next)){closeModal();toast(`Sale recorded. ${next.quantity} units remain.`)}}catch(err){$('#sale-error').textContent=err.message}})}
function renderSettings(){const s=state.settings;$('#admin-content').innerHTML=`<form id="settings-form" class="settings-form"><h3>The conversation starts here.</h3>${field('Business WhatsApp number — optional','whatsapp',s.whatsapp,'tel','placeholder="e.g. 919876543210" maxlength="20"')}<small>Include country code, digits only. Leave blank to preview messages without contacting anyone. Do not use an unapproved number.</small><h3>Business & ordering information.</h3>${[['about','About Drip & Dusk'],['ordering','How enquiries and orders work'],['shipping','Shipping information'],['payment','Payment, returns & cancellation information'],['faq','FAQs — one question|answer per line'],['reviews','Genuine customer reviews — leave placeholder until supplied']].map(([key,label])=>`<label>${label}<textarea name="${key}" maxlength="6000">${esc(s[key])}</textarea></label>`).join('')}<p id="settings-error" class="form-error" role="alert"></p><button class="btn" type="submit">Save business information ↗</button></form><div class="settings-danger"><h3>Start fresh.</h3><p>Restore the sample catalogue, settings, enquiry bag and favourites on this device.</p><button class="btn outline" data-action="reset">Reset demo data</button></div>`;$('#settings-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),next=structuredClone(state),num=f.get('whatsapp').trim();if(num&&!/^[1-9]\d{7,14}$/.test(num)){ $('#settings-error').textContent='Enter 8–15 digits including country code, with no +, spaces or leading zero. Or leave the field blank.';return}for(const key of ['whatsapp','about','ordering','shipping','payment','faq','reviews'])next.settings[key]=String(f.get(key)).trim();if(!next.settings.about||!next.settings.ordering||!next.settings.shipping||!next.settings.payment){$('#settings-error').textContent='Keep about, ordering, shipping and payment fields filled. Use pending-approval text where details are missing.';return}if(commit(next))toast('Business information saved on this device.')})}
function confirmAction(title,body,action,id=''){openModal(title,`<p>${esc(body)}</p><div class="modal-buttons"><button class="btn outline" data-action="close">Cancel</button><button class="btn danger" data-action="${action}" data-id="${esc(id)}">Confirm ${action==='confirm-reset'?'reset':action==='confirm-delete'?'delete':'archive'}</button></div>`,'confirm','OWNER STUDIO')}
function route(){const h=location.hash||'#home';if(h==='#admin'){$('#storefront').hidden=true;$('#admin').hidden=false;closeModal(false);renderAdmin();window.scrollTo({top:0,behavior:'instant'});return}const wasAdmin=!$('#admin').hidden;$('#storefront').hidden=false;$('#admin').hidden=true;if(h.startsWith('#product/')){let id;try{id=decodeURIComponent(h.slice(9))}catch{return}openProduct(id);return}if(modalType==='product')closeModal(false);if(wasAdmin)requestAnimationFrame(()=>$(h)?.scrollIntoView());}
$('#catalogue-search').addEventListener('input',e=>{filters.query=e.target.value;renderCatalogue()});for(const name of ['brand','budget','stock','sort'])$('#'+name+'-filter').addEventListener('change',e=>{filters[name]=e.target.value;renderCatalogue()});$('#filter-toggle').addEventListener('click',()=>{const p=$('#filter-panel');p.hidden=!p.hidden;$('#filter-toggle').setAttribute('aria-expanded',String(!p.hidden))});
modal.addEventListener('cancel',e=>{e.preventDefault();closeModal()});modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
document.addEventListener('input',e=>{if(e.target.id==='admin-search'){adminQuery=e.target.value;renderAdminProducts()}});
document.addEventListener('change',e=>{if(e.target.id==='admin-scope'){adminScope=e.target.value;renderAdminProducts()}if(e.target.matches('[data-bag-qty]')){const qty=Number(e.target.value),id=e.target.dataset.bagQty;changeBag(id,qty);if(modalType==='basket')openBasket()}});
document.addEventListener('click',e=>{
 const edit=e.target.closest('[data-edit]');if(edit&&!edit.disabled){clearFilters();filters.collection=edit.dataset.edit;filters.kind='Full bottle';renderCatalogue();location.hash='#collection';$('#collection').scrollIntoView({behavior:'smooth'});return}const kind=e.target.closest('[data-kind]');if(kind){filters.kind=kind.dataset.kind;renderCatalogue();return}const tab=e.target.closest('[data-admin-tab]');if(tab){adminTab=tab.dataset.adminTab;renderAdmin();return}if(e.target.closest('[data-focus-search]'))setTimeout(()=>$('#catalogue-search').focus(),50);
 const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,id=el.dataset.id,p=state.products.find(p=>p.id===id);
 if(a==='close')closeModal();if(a==='browse'){closeModal();location.hash='#collection'}if(a==='basket'){if(modalType==='product'&&location.hash.startsWith('#product/'))history.replaceState(null,'','#collection');openBasket()}
 if(a==='add')addToBag(id);if(a==='save')favourite(id);if(a==='clear-filters')clearFilters();if(a==='show-favourites'){filters.kind='saved';renderCatalogue();location.hash='#collection'}
 if(a==='motion')heroMotion?.toggle();if(a==='clear-edit'){filters.collection='';renderCatalogue()}if(a==='image-view'){const detail=el.dataset.view==='detail';$('.detail-image').classList.toggle('zoomed',detail);$$('[data-action=image-view]').forEach(b=>{const active=b===el;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})}
 if(a==='detail-minus'||a==='detail-plus'){const input=$('#detail-quantity'),n=Number(input.value)+(a==='detail-plus'?1:-1);input.value=Math.max(1,Math.min(Number(input.max),n))}
 if(a==='detail-add')addToBag(id,Number($('#detail-quantity').value));if(a==='enquire-product'){const qty=Number($('#detail-quantity').value);previewMessage([{id,qty}])}
 if(a==='share-product'){const url=new URL(location.href);url.hash='product/'+id;copy(url.href,'Product link copied. It opens this exact size and format.')}if(a==='contact')previewMessage([],true);
 if(a==='bag-remove'){if(saveBag(basket.filter(l=>l.id!==id)))openBasket()}if(a==='bag-plus'||a==='bag-minus'){const l=basket.find(l=>l.id===id);if(l)changeBag(id,l.qty+(a==='bag-plus'?1:-1))}if(a==='preview-basket')previewMessage();if(a==='copy-message')copy($('#message-preview').value,'Message copied.');
 if(a==='new-product')editProduct();if(a==='edit')editProduct(id);if(a==='duplicate')editProduct(id,true);if(a==='price')priceModal(id);if(a==='sale')saleModal(id);
 if(a==='stock-toggle'){if(p.available&&p.quantity>0){if(updateProduct(id,p=>({...p,available:false})))toast('Marked sold out. Enquiries for this variant are disabled.')}else editProduct(id)}
 if(a==='hide'){if(updateProduct(id,p=>({...p,hidden:!p.hidden})))toast(p.hidden?'Product shown on the storefront.':'Product hidden from the storefront.')}
 if(a==='archive')confirmAction('Archive this fragrance?',`${p.name} · ${p.size} ml will be removed from the storefront. You can restore it from Archive.`,'confirm-archive',id);
 if(a==='confirm-archive'){if(updateProduct(id,p=>({...p,archived:true}))){closeModal();toast('Product archived.')}}
 if(a==='restore'){if(updateProduct(id,p=>({...p,archived:false})))toast('Product restored. Check its visibility and stock.')}
 if(a==='delete')confirmAction('Permanently delete?',`${p.name} · ${p.size} ml will be permanently removed from this browser’s demo. Existing bag entries will become unavailable.`,'confirm-delete',id);
 if(a==='confirm-delete'){const next=structuredClone(state);next.products=next.products.filter(p=>p.id!==id);if(commit(next)){closeModal();toast('Product deleted.')}}
 if(a==='reset')confirmAction('Reset this browser’s demo?','This removes local catalogue edits, uploaded images, settings, favourites and your enquiry bag. The original sample data will be restored.','confirm-reset');
 if(a==='confirm-reset'){const next=defaults();if(commit(next)){saveBag([]);if(write(KEY+'-saved',[]))saved=[];renderStore();renderAdmin();closeModal();toast('Original demo data restored.')}}
});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!modal.open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();if(location.hash==='#admin')$('#admin-search')?.focus();else{location.hash='#collection';$('#catalogue-search').focus()}}});
window.addEventListener('hashchange',route);window.addEventListener('storage',e=>{if(![KEY,KEY+'-bag',KEY+'-saved'].includes(e.key))return;const next=read(KEY,defaults());if(next?.version===1&&Array.isArray(next.products)&&next.settings)state=next;basket=read(KEY+'-bag',[]);saved=read(KEY+'-saved',[]);renderStore();if(location.hash==='#admin')renderAdmin();if(modalType==='basket')openBasket();if(modalType==='product')openProduct(currentId,false);toast('Demo data updated from another tab.')});
renderStore();route();heroMotion=initHeroVideo();if(storageNotice)toast(storageNotice);
